:root{--ink:#172e3a;--night:#142b37;--cream:#fff7e9;--paper:#f7ebd5;--gold:#ffca70;--coral:#ec846d;--sage:#b8d7b1;--line:#d8cab5}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:'Trebuchet MS',sans-serif;line-height:1.5}button{font:inherit;cursor:pointer}a{color:inherit}a:focus-visible,button:focus-visible{outline:3px solid #d05b41;outline-offset:4px}header{background:var(--night);color:var(--cream);padding:18px max(22px,calc((100vw - 1160px)/2));display:flex;align-items:center;justify-content:space-between;gap:16px}header a{text-decoration:none;font-size:.82rem;font-weight:700}header .brand{font-family:Georgia,serif;font-size:1.15rem;letter-spacing:-.02em}header .back{border-bottom:1px solid #b8d7b1;padding-bottom:2px}.hero{background:var(--night);color:var(--cream);overflow:hidden}.hero-inner{max-width:1160px;margin:auto;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);align-items:center;min-height:470px;gap:30px;padding:45px 24px 64px}.eyebrow{font-size:.75rem;letter-spacing:.2em;text-transform:uppercase;font-weight:700;color:var(--gold)}h1,h2,h3{font-family:Georgia,serif;line-height:1.08;letter-spacing:-.035em}h1{font-size:clamp(3.5rem,7vw,6.7rem);margin:12px 0 22px}h1 em{color:var(--gold);font-weight:500}.hero p{font-size:1.05rem;max-width:520px;color:#e5e5d8}.art-frame{border:8px solid #f6e9cf;box-shadow:15px 18px 0 #0b202b;transform:rotate(2deg);position:relative}.art-frame:after{content:'A SMALL THING CAN BE A BRIDGE';position:absolute;bottom:-23px;left:8px;font-size:.58rem;color:#31434b;font-weight:700;letter-spacing:.16em;background:var(--cream);padding:3px 8px}.art-frame img{display:block;width:100%;aspect-ratio:3/2;object-fit:cover}.art-frame img:not([src]){display:none}.intro{max-width:1160px;margin:auto;padding:45px 24px 10px;display:grid;grid-template-columns:1fr 1fr;gap:36px}.intro h2{font-size:clamp(2rem,4vw,3.2rem);margin:0}.intro p{max-width:520px;margin:5px 0 0}.game{max-width:1160px;margin:auto;padding:28px 24px 80px}.dashboard{background:var(--ink);color:var(--cream);border-radius:18px 18px 0 0;padding:24px 30px;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.dashboard h2{font-size:1.55rem;margin:0}.budget{display:flex;gap:24px;flex-wrap:wrap}.budget div{font-size:.72rem;text-transform:uppercase;letter-spacing:.12em;color:#d0d8d3}.budget strong{display:block;color:var(--gold);font-family:Georgia,serif;font-size:2rem;line-height:1.2;letter-spacing:0;text-transform:none}.track{height:7px;background:#e2d0b7}.track span{height:100%;display:block;background:var(--coral);transition:width .35s}.game-body{background:#fffaf0;border:1px solid var(--line);border-top:0;border-radius:0 0 18px 18px;padding:26px 30px 32px}.instruction{margin:0 0 22px;font-size:.88rem;color:#49606a}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{border:1px solid #d6c5a9;border-radius:12px;background:#fffdf7;overflow:hidden;transition:transform .2s,box-shadow .2s}.card:hover{transform:translateY(-3px);box-shadow:0 10px 26px #172e3a16}.card.done{background:#ecf3e6;border-color:#9cb68c}.card-head{padding:20px 22px 14px;display:flex;gap:15px}.symbol{width:48px;height:48px;border-radius:50%;background:#f4dfbd;display:grid;place-items:center;font-size:1.5rem;flex:none}.card.done .symbol{background:#d6e8cf}.card small{font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.14em;color:#826d52}.card h3{margin:3px 0 8px;font-size:1.55rem}.card p{margin:0;color:#41515a;font-size:.91rem}.options{padding:0 20px 20px;display:grid;gap:8px}.option{width:100%;background:#fff7e8;border:1px solid #d6c5a9;border-radius:8px;padding:11px 12px;text-align:left;display:flex;justify-content:space-between;align-items:center;gap:10px;min-height:60px;transition:background .2s,transform .2s}.option:hover:not(:disabled){background:var(--gold);transform:translateX(3px)}.option:disabled{opacity:.43;cursor:not-allowed}.option .cost{white-space:nowrap;font-size:.76rem;font-weight:700;color:#7d4b34}.ripple{padding:0 22px 20px;font-size:.9rem}.ripple b{display:block;color:#41674b;margin-bottom:4px}.ripple button{border:0;background:none;color:#496d50;text-decoration:underline;padding:8px 0 0}.footer-row{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:22px}.reset{background:transparent;border:1px solid #ad9c83;border-radius:5px;padding:10px 15px;font-weight:700}.reset:hover{background:#f0e4d0}.status{font-size:.9rem;color:#4b5b62}.ending{display:none;margin-top:24px;border:2px dashed #b69d75;background:#fff2d4;padding:24px;border-radius:12px}.ending.show{display:block;animation:appear .5s both}.ending h3{font-size:2rem;margin:4px 0 10px}.ending p{margin:0}.end-note{font-size:.78rem;color:#63717a;margin-top:8px!important}@keyframes appear{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}.about{max-width:1160px;margin:0 auto 80px;padding:0 24px;display:grid;grid-template-columns:1fr 1fr;gap:40px}.about h2{font-size:2rem;margin:0}.about p{margin:0 0 12px}.about a{font-weight:700;text-decoration-thickness:2px;text-underline-offset:4px}footer{background:var(--night);color:#dee5d9;padding:30px 24px;text-align:center;font-size:.8rem}footer a{color:var(--gold)}@media(max-width:740px){header{padding:16px 20px}.hero-inner{display:flex;flex-direction:column;align-items:stretch;padding:34px 24px 55px;gap:28px;min-height:0}h1{font-size:clamp(3.5rem,13vw,5.4rem)}.art-frame{margin:0 12px 0 0}.intro,.about{grid-template-columns:1fr;gap:12px}.intro{padding-top:42px}.game{padding-top:20px}.cards{grid-template-columns:1fr}.dashboard,.game-body{padding:22px 18px}.budget{gap:18px}.budget strong{font-size:1.6rem}.card-head{padding:18px}.options{padding:0 18px 18px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
